param([string]$Destination = 'C:\Users\Dhrubo\Desktop\INDUCTO_VISUAL_ASSETS')
$ErrorActionPreference='Stop'
$root=(Get-Location).Path
$decks=Get-Content (Join-Path $root 'pptx_extract.json') -Raw|ConvertFrom-Json
$modules=@($decks|Where-Object filename -ne '00-master-index.pptx'|Sort-Object relative_path)
$folderMap=@{'01'='01_AI_FUNDAMENTALS';'02'='02_DAY_TO_DAY_WORK';'03'='03_PROMPT_ENGINEERING';'04'='04_PROFESSIONAL_SKILLS';'05'='05_SECURITY_DATA_PRIVACY'}
$catMap=@{'01'='AI Fundamentals';'02'='AI for Day-to-Day Work';'03'='Prompt Engineering';'04'='Professional Skills';'05'='Security & Data Privacy'}
$dirs=@($folderMap.Values)+'SHARED'
New-Item -ItemType Directory -Force -Path $Destination|Out-Null
foreach($dir in $dirs){New-Item -ItemType Directory -Force -Path (Join-Path $Destination $dir)|Out-Null}

function Parts($text){,@($text -split '\s*\|\s*'|Where-Object {$_ -and $_ -notmatch 'Inducto Learning Library|^Menu$'})}
function Clean($s){ if(!$s){return ''}; (($s -replace '[\r\n]+',' ' -replace '\s+',' ').Trim()) }
function Slug($s){$x=(Clean $s).ToLowerInvariant() -replace '[^a-z0-9]+','_';$x.Trim('_')}
function Csv($s){'"'+((Clean $s)-replace '"','""')+'"'}

$inventory=@('# Source Module Inventory','','Source of truth: all PPTX files recursively discovered in the working directory. Extracted directly from the Open XML packages, including slide text, notes and external relationships.','','- Source decks: 40 (39 modules plus one master index)','- Extracted slides: '+(($decks|Measure-Object slide_count -Sum).Sum),'- Categories: 5','')
$manifest=@('asset_id,filename,relative_path,module,source_ppt_filename,lesson_topic,asset_type,purpose,visual_description,learning_objective,recommended_placement,recommended_display_type,aspect_ratio,generation_status,QA_status,source_slide,interaction_support,video_relationship,prompt')
$index=@('# Asset Index','','This index lists planned production assets. Use `ASSET_MANIFEST.csv` as the machine-readable authority and `PLACEMENT_MAP.md` for semantic placement.','')
$placement=@('# Placement Map','','Every placement is tied to a source slide and learning purpose. Do not use these assets decoratively.','')
$queue=@('# Image Generation Queue','','Production-ready queue for assets not yet generated. Every prompt is grounded in a source slide. Generate one file per entry at the exact relative path.','')
$records=@()

foreach($m in $modules){
 $prefix=$m.filename.Substring(0,2);$folder=$folderMap[$prefix];$p1=Parts $m.slides[0].text
 $title=Clean $p1[1];$id=Clean ($p1|Where-Object{$_ -match '^(AI|DW|PE|PS|SEC)-\d+'}|Select-Object -First 1)
 $duration=Clean ($p1|Where-Object{$_ -match 'MINUTES'}|Select-Object -First 1);$aud=Clean ($p1|Where-Object{$_ -match 'JOINERS|STAFF|MANDATORY'}|Select-Object -First 1)
 $obj=Parts $m.slides[2].text;$objectives=@($obj|Where-Object{$_ -notmatch "WHAT YOU'LL|By the end|^$id"}|Select-Object -First 5)
 $scenario=Parts $m.slides[1].text;$scenarioTitle=Clean ($scenario|Where-Object{$_ -notmatch 'WHY THIS|^'+[regex]::Escape($id)}|Select-Object -First 1)
 $links=@($m.slides|ForEach-Object links|Where-Object{$_})
 $contentSlides=@($m.slides|Where-Object{$_.slide -ge 5 -and $_.text -notmatch 'QUIZ\s*·|YOU CHOSE|Not quite|Correct —|GLOSSARY|YOUR TOOLKIT'})
 $lessonNames=@($contentSlides|ForEach-Object{(Parts $_.text)[1]}|Where-Object{$_}|Select-Object -Unique)
 $scenarios=@($m.slides|Where-Object{$_.text -match "CHOOSE WHAT YOU'D DO"})
 $exercises=@($m.slides|Where-Object{$_.text -match 'DO THIS NOW|EXERCISE|TRY THIS'})
 $quizzes=@($m.slides|Where-Object{$_.text -match 'QUIZ\s*·\s*QUESTION'})
 $recap=@($m.slides|Where-Object{$_.text -match 'RECAP CARD'})
 $inventory+=@("## $id — $title",'',"- Filename: `$($m.relative_path)`","- Category: $($catMap[$prefix])","- Duration: $duration","- Audience: $aud","- Slides: $($m.slide_count)","- Opening workplace situation: $scenarioTitle","- Learning objectives: "+(($objectives|ForEach-Object{Clean $_}) -join '; '),"- Lesson structure: "+(($lessonNames|ForEach-Object{Clean $_}) -join '; '),"- Scenario decision slides: $($scenarios.Count)","- Exercises/action slides: $($exercises.Count)","- Quiz questions: $($quizzes.Count)","- Recap cards: $($recap.Count)","- External/video links: $($links.Count)",'')

 $candidates=@()
 $candidates += [pscustomobject]@{slide=$m.slides[1];type='scenario illustration';topic=$scenarioTitle;display='full-width scenario';ratio='16:9';interaction='scenario introduction'}
 $picks=@($contentSlides|Where-Object{$_.slide -notin @($scenarios.slide)})
 if($picks.Count -gt 0){foreach($idx in @(0,[math]::Floor($picks.Count*.2),[math]::Floor($picks.Count*.4),[math]::Floor($picks.Count*.6),[math]::Floor($picks.Count*.8))|Select-Object -Unique){if($idx -lt $picks.Count){$candidates += [pscustomobject]@{slide=$picks[$idx];type='instructional concept visual';topic=(Parts $picks[$idx].text)[1];display='inline lesson visual';ratio='3:2';interaction='click-to-reveal or workflow exploration'}}}}
 if($scenarios.Count){$candidates += [pscustomobject]@{slide=$scenarios[0];type='decision situation';topic=(Parts $scenarios[0].text)[1];display='scenario choice hero';ratio='16:9';interaction='What would you do?'}}
 if($quizzes.Count){$candidates += [pscustomobject]@{slide=$quizzes[0];type='knowledge-check visual';topic=(Parts $quizzes[0].text)[1];display='question context';ratio='4:3';interaction='mini quiz'}}
 if($recap.Count){$candidates += [pscustomobject]@{slide=$recap[0];type='recap visual';topic=(Parts $recap[0].text)[1];display='recap card';ratio='1:1';interaction='recap reveal'}}
 $n=0;$moduleRows=@()
 foreach($c in ($candidates|Select-Object -First 10)){
  $n++;$assetId=($id -replace '-','')+'-'+('{0:D2}' -f $n);$topic=Clean $c.topic;if(!$topic){$topic="Source slide $($c.slide.slide)"}
  $slug=Slug $topic;if($slug.Length -gt 55){$slug=$slug.Substring(0,55).TrimEnd('_')}
  $filename="${assetId}_$slug.png";$rel="$folder/$filename"
  $raw=Clean $c.slide.text;if($raw.Length -gt 850){$raw=$raw.Substring(0,850)}
  $objective=if($objectives.Count){Clean $objectives[[Math]::Min($n-1,$objectives.Count-1)]}else{"Understand $topic"}
  $place=if($c.type -eq 'scenario illustration'){'Immediately after the module opener, before the scenario explanation.'}elseif($c.type -eq 'decision situation'){'Directly above the scenario options.'}elseif($c.type -eq 'knowledge-check visual'){'Immediately before the answer choices.'}elseif($c.type -eq 'recap visual'){'Alongside the recap card at module close.'}else{"Adjacent to source slide $($c.slide.slide)'s lesson content."}
  $safe='Use only fictional/synthetic details; no real personal, bank, credential, customer or confidential data.'
  $prompt="Use case: illustration-story. Asset type: premium enterprise learning visual. Primary request: Visually explain '$topic' from module '$title'. Source-grounded content: $raw. Scene/backdrop: believable contemporary Indian corporate, factory, logistics or office setting appropriate to the source. Style/medium: refined editorial illustration with realistic proportions, clean geometry, subtle texture, premium learning-platform finish. Composition/framing: $($c.ratio) composition, one clear focal idea, readable at web size. Constraints: preserve source meaning; $safe no logos, no watermark, no flags, no generic robots, no glowing brains, no long text. Avoid: stock-photo staging, stereotypes, malformed hands, fake UI text, clutter."
  $row=[pscustomobject]@{asset_id=$assetId;filename=$filename;relative_path=$rel;module="$id $title";source_ppt_filename=$m.filename;lesson_topic=$topic;asset_type=$c.type;purpose="Make the source learning point '$topic' easier to understand and remember.";visual_description="Source-faithful visual representation of slide $($c.slide.slide): $topic, using a contemporary Indian workplace context where people are shown.";learning_objective=$objective;recommended_placement=$place;recommended_display_type=$c.display;aspect_ratio=$c.ratio;generation_status='pending_generation';QA_status='not_started';source_slide=$c.slide.slide;interaction_support=$c.interaction;video_relationship=if($c.slide.links.Count){'Supports linked external content; not a fake thumbnail'}else{'none'};prompt=$prompt}
  $records+=$row;$moduleRows+=$row
  $manifest+=(($row.psobject.Properties.Value|ForEach-Object{Csv $_}) -join ',')
  $placement+=@("## $assetId — $topic",'',"- Module: $id $title","- Lesson: $topic","- Asset: `$filename`","- Source: `$($m.filename)`, slide $($c.slide.slide)","- Placement: $place","- Why: $($row.purpose)","- Learning point: $objective","- Interaction support: $($c.interaction)",'')
  $queue+=@("## $assetId",'',"- Filename: `$filename`","- Path: `$rel`","- Aspect ratio: $($c.ratio)","- Source: `$($m.filename)`, slide $($c.slide.slide)","- Placement: $place",'',"Prompt: $prompt",'')
 }
 $index+=@("## $id — $title",'')+($moduleRows|ForEach-Object{"- `$($_.filename)` — $($_.asset_type); $($_.lesson_topic); $($_.interaction_support)"})+''
}

$style=@('# Style Guide','','## Communication job','','By the end, a new joiner should understand and act on each source lesson because every visual isolates one workplace decision, workflow or concept without replacing the authoritative copy.','','## Visual system','','- Premium editorial enterprise-learning aesthetic; contemporary Indian workplaces without stereotypes.','- Natural materials, restrained texture, realistic proportions and clean geometry.','- Palette: deep navy, warm white, slate, teal accents; amber for caution; red only for risk/stop.','- One focal idea per image. Avoid decorative dashboards, generic robots, glowing brains and meaningless technology backgrounds.','- People: fictional Indian professionals in credible office, factory, warehouse and logistics contexts; varied age, gender and role.','- Text: none by default. Short labels only when essential; HTML remains authoritative.','- Major scenarios 16:9; supporting concepts 3:2 or 4:3; recap cards 1:1.','- Safe synthetic data in all security, privacy, finance and AI-input scenes.','','## Composition rules','','- Reserve negative space only when the placement map calls for adjacent HTML copy.','- Show cause and effect, comparison, decision or workflow—not generic activity.','- Devices and documents must look plausible but must not contain readable sensitive information.','- Never include real logos, branding or watermarks.')
$chars=@('# Character Reference','','All characters are fictional composites; they must never resemble a real employee. Reuse these anchors when a module scenario calls for continuity.','',
'| ID | Role | Age | Professional context | Visual characteristics | Clothing | Environment | Modules |','|---|---|---:|---|---|---|---|---|',
'| CH-RAMESH | Dispatch coordinator | 35–45 | Warehouse operations | Medium build, short black hair, trimmed moustache | Light blue shirt, navy safety vest | Bhiwandi-style modern warehouse | AI-01 |',
'| CH-DEEPA | MIS analyst | 28–38 | Office/data work | Shoulder-length black hair, rectangular glasses | Teal blouse, charcoal trousers | Chennai corporate office | AI-03, DW-04 |',
'| CH-SURESH | Maintenance planner | 35–45 | Manufacturing/Excel work | Short wavy hair, clean-shaven | Checked shirt, plant ID lanyard | Coimbatore-style plant office | DW-05 |',
'| CH-TANVI | Business analyst/presenter | 28–38 | Group-office reviews | Long tied-back hair, confident posture | Navy blazer, cream top | Mumbai corporate meeting room | DW-06 |',
'| CH-REKHA | Accounts payable specialist | 32–42 | Supplier payments | Bob-length black hair, calm expression | Rust kurta-style office top, dark trousers | Indian corporate finance office | SEC-02 |',
'| CH-AYESHA | HR operations specialist | 28–38 | HR records and authentication | Wavy black hair, round glasses | Grey blazer, muted green blouse | Secure office workstation | SEC-03 |',
'| CH-FARHAN | Accounts executive | 25–35 | AI-assisted document work | Short black hair, light beard | White shirt, dark waistcoat | Indian office | SEC-07 |',
'| CH-NEHA | Training writer | 28–38 | Review and quality control | Curly shoulder-length hair | Indigo shirt, grey trousers | Noida-style collaborative office | PE-07 |')
$handoff=@('# Claude Code Handoff','','## Library overview',"This package maps $($records.Count) planned learning visuals to 39 authoritative PPTX modules. The CSV is the machine-readable source; the placement map explains semantic use. Generated assets have `generation_status=generated`; pending rows must not be referenced as files.",'','## Folder structure','Five category folders mirror the source library; `SHARED` is reserved for genuinely cross-module assets. Root documents govern source traceability, style, generation and QA.','','## Consumption rules','1. Load `ASSET_MANIFEST.csv` and filter to `generation_status=generated` and `QA_status=approved`.','2. Match by module ID, lesson/topic and source slide—not by filename keywords alone.','3. Read the corresponding `PLACEMENT_MAP.md` entry before placing an asset.','4. Use scenario assets before choices; concept visuals beside the relevant explanation; recap visuals only at close.','5. Keep HTML copy authoritative. Do not transcribe generated-image text as instruction.','6. Reuse only assets in `SHARED`; do not reuse a module-specific scenario elsewhere.','7. Preserve aspect ratio and focal crop; do not stretch.','8. Treat external-video support as context only; never present it as an authentic video thumbnail.','','## Naming convention','`<module-id-without-hyphen>-<sequence>_<descriptive_source_topic>.png`. IDs and paths are deterministic and unique.','','## Interaction support','Use the `interaction_support` column to select click-to-reveal, scenario question, decision, workflow, quiz-context and recap assets. The image is context; interaction state and feedback remain accessible HTML.','','## What not to do','- DO NOT place images merely because space exists. Images must improve comprehension, context, scenario understanding or interaction.','- Do not use pending or rejected assets.','- Do not use security imagery containing readable personal, customer, bank, password or confidential data.','- Do not infer new learning claims from visual details.','- Do not turn scenario art into decoration or use a wrong character/module context.','','## Preserve source meaning','The PPTX filename and source slide columns are mandatory provenance. When wording and imagery appear to conflict, the PPTX wins. Escalate unresolved placeholders such as `[COMPANY INPUT NEEDED]` instead of inventing company policy.')
$log=@('# Generation Log','','Built-in ImageGen capability detected. Asset rows begin as pending and are updated only after a real file is generated, saved to its manifest path, opened successfully and visually inspected.','','| Asset ID | Attempt | Status | Notes |','|---|---:|---|---|')
$qa=@('# QA Report','','## Status','','Full visual QA is pending for queued images. No asset is approved until its file opens and is checked for scenario accuracy, Indian context, style consistency, anatomy, devices, text, logos, relevance and sensitive-data safety.','','## Acceptance checklist','','- Correct source scenario and learning purpose','- Believable contemporary Indian context where people appear','- No distorted people, malformed hands/faces or broken devices','- No unreadable or fabricated instructional text','- No logos, branding, flags, watermarks or stereotypes','- No real or plausible sensitive data','- No duplicate/near-duplicate concept','- Correct ratio, crop and filename','- Manifest and placement paths resolve','','## Current result','','Pending generation: '+$records.Count,'Generated: 0','Approved: 0','Rejected: 0','Regenerated: 0')
$audit=@('# Final Asset Audit','','This audit is regenerated after every production/QA pass.','','- Source PPT/PPTX files: 40','- Training modules discovered: 39','- Extracted slides: 1,970',"- Planned visual assets: $($records.Count)",'- Generated assets: 0','- Failed generations: 0','- Rejected assets: 0','- Regenerated assets: 0',"- Pending generations: $($records.Count)",'- Shared assets: 0',"- Final output location: `$Destination`",'','## Assets by module','')
$records|Group-Object module|ForEach-Object{$audit+="- $($_.Name): $($_.Count) planned"}
$audit+=@('','## Human attention','','- Resolve all `[COMPANY INPUT NEEDED]` placeholders in the source before implementation.','- Only files marked generated and QA-approved may be consumed by the platform.','- Pending queue entries remain specifications, not completed images.')

$files=@{'SOURCE_MODULE_INVENTORY.md'=$inventory;'ASSET_INDEX.md'=$index;'ASSET_MANIFEST.csv'=$manifest;'PLACEMENT_MAP.md'=$placement;'IMAGE_GENERATION_QUEUE.md'=$queue;'STYLE_GUIDE.md'=$style;'CHARACTER_REFERENCE.md'=$chars;'CLAUDE_HANDOFF.md'=$handoff;'GENERATION_LOG.md'=$log;'QA_REPORT.md'=$qa;'FINAL_ASSET_AUDIT.md'=$audit}
foreach($kv in $files.GetEnumerator()){Set-Content -LiteralPath (Join-Path $Destination $kv.Key) -Value $kv.Value -Encoding utf8}
Write-Output ("Built library: {0} modules, {1} queued assets at {2}" -f $modules.Count,$records.Count,$Destination)
